def point_in_triangle(p, a, b, c):
    def sign(p1, p2, p3):
        return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p3[0] - p1[0]) * (p2[1] - p1[1])

    d1 = sign(p, a, b)
    d2 = sign(p, b, c)
    d3 = sign(p, c, a)

    has_neg = (d1 < 0) or (d2 < 0) or (d3 < 0)
    has_pos = (d1 > 0) or (d2 > 0) or (d3 > 0)

    # If all signs are the same, the point is outside the triangle
    if has_neg and has_pos:
        return False

    # Check if the point is on an edge
    def on_segment(p, a, b):
        # Check if p lies on the line segment ab
        def between(x, a, b):
            return (min(a, b) <= x <= max(a, b))
        # Check if p is collinear and lies between a and b
        return (sign(p, a, b) == 0 and between(p[0], a[0], b[0]) and between(p[1], a[1], b[1]))

    return on_segment(p, a, b) or on_segment(p, b, c) or on_segment(p, c, a)
