def is_point_on_segment(p, a, b):
    # Check if p lies on the line defined by a and b
    # Using the cross product to check collinearity
    def cross(x1, y1, x2, y2):
        return x1 * y2 - y1 * x2

    # Check if p is collinear with a and b
    if cross(p[0] - a[0], p[1] - a[1], b[0] - a[0], b[1] - a[1]) != 0:
        return False

    # Check if p is between a and b (inclusive)
    def is_between(x, y, a, b):
        return min(a, b) <= x <= max(a, b) and min(y, b) <= y <= max(y, b)

    return is_between(p[0], p[1], a[0], b[0]) and is_between(p[1], p[0], a[1], b[1])
```

