def is_convex_polygon(points):
    def cross(o, a, b):
        # Compute the cross product of OA and OB
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False  # Not a polygon

    # Check if all points are collinear
    if all(cross(points[0], points[i], points[(i + 1) % n]) == 0 for i in range(1, n - 1)):
        return False

    # Check all consecutive triplets of points to ensure all cross products have the same sign
    sign = 0
    for i in range(n):
        o = points[i]
        a = points[(i + 1) % n]
        b = points[(i + 2) % n]
        c = cross(o, a, b)
        if c == 0:
            continue  # Collinear points, not a problem for convexity
        if c > 0:
            if sign < 0:
                return False
            sign = 1
        else:
            if sign > 0:
                return False
            sign = -1

    return True
```

