def is_convex_polygon(points):
    def cross(o, a, b):
        # Calculate the cross product of vectors OA and OB
        # Returns positive if O->A->B is counter-clockwise, negative if clockwise, zero if collinear
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False

    # Check all consecutive triplets of points
    prev_cross = 0
    for i in range(n):
        a = points[i]
        b = points[(i + 1) % n]
        c = points[(i + 2) % n]
        cross_prod = cross(a, b, c)

        if cross_prod == 0:
            # Collinear points, not a valid convex polygon
            return False

        if i == 0:
            prev_cross = cross_prod
        else:
            if (cross_prod > 0 and prev_cross < 0) or (cross_prod < 0 and prev_cross > 0):
                # The direction of the turn changed, so not convex
                return False
            prev_cross = cross_prod

    return True
```

