def is_convex_polygon(points):
    def cross(p, q, r):
        # Compute the cross product of vectors (q - p) and (r - p)
        return (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])

    n = len(points)
    if n < 3:
        return False  # Not a polygon

    # Check the sign of all consecutive cross products
    prev = None
    for i in range(n):
        p = points[i]
        q = points[(i + 1) % n]
        r = points[(i + 2) % n]
        curr = cross(p, q, r)
        if curr == 0:
            # Points are collinear, not a valid convex polygon
            return False
        if prev is None:
            prev = curr
        else:
            if (prev > 0 and curr < 0) or (prev < 0 and curr > 0):
                # The cross product changed sign, polygon is concave
                return False
        prev = curr

    return True
```

