    # Create a deep copy of the grid to avoid modifying the original
    new_grid = [row[:] for row in grid]

    # Iterate through each cell in the grid
    for i in range(len(new_grid)):
        for j in range(len(new_grid[i])):
            if new_grid[i][j] == old:
                new_grid[i][j] = new

    return new_grid
