def parse_ini_line(line):
    # Strip leading and trailing whitespace from the entire line
    line = line.strip()
    # Split the line on the first occurrence of '='
    parts = line.split('=', 1)
    if len(parts) < 2:
        # If there's no '=', return the whole line as the key and empty string as the value
        return (line, '')
    key, value = parts
    # Strip whitespace from key and value
    return (key.strip(), value.strip())
