def parse_simple_expr(s):
    # Iterate through the string to find the operator
    for i, char in enumerate(s):
        if char in "+-*/":
            # Split the string into left and right operands
            left = int(s[:i])
            right = int(s[i+1:])
            operator = char
            break
    else:
        # No operator found (should not happen per problem statement)
        raise ValueError("Invalid expression")

    # Perform the operation
    if operator == '+':
        return left + right
    elif operator == '-':
        return left - right
    elif operator == '*':
        return left * right
    elif operator == '/':
        return left / right
```

