def parse_url_parts(url):
    # Split the URL into scheme and the rest
    if '://' not in url:
        return {'scheme': '', 'host': '', 'path': '', 'query': ''}

    scheme, rest = url.split('://', 1)

    # Split the rest into host, path, and query
    host_end = rest.find('/')
    query_pos = rest.find('?')

    if host_end == -1:
        host_end = query_pos if query_pos != -1 else len(rest)
    elif query_pos != -1 and query_pos < host_end:
        host_end = query_pos

    host = rest[:host_end]
    path = rest[host_end:query_pos] if query_pos != -1 else rest[host_end:]
    query = rest[query_pos+1:] if query_pos != -1 else ''

    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
```

```python
def parse_url_parts(url):
    # Split the URL into scheme and the rest
    if '://' not in url:
        return {'scheme': '', 'host': '', 'path': '', 'query': ''}

    scheme, rest = url.split('://', 1)

    # Split the rest into host and the remaining part
    host_end = rest.find('/')
    if host_end == -1:
        host_end = rest.find('?')
    if host_end == -1:
        host_end = len(rest)

    host = rest[:host_end]
    remaining = rest[host_end:]

    # Determine path and query
    if '?' in remaining:
        path_part, query = remaining.split('?', 1)
    else:
        path_part = remaining
        query = ''

    return {
        'scheme': scheme,
        'host': host,
        'path': path_part if path_part.startswith('/') else '/' + path_part,
        'query': query
    }
```

