def traffic_light_state(n_ticks, durations):
    red_ticks, green_ticks, yellow_ticks = durations
    total_cycle = red_ticks + green_ticks + yellow_ticks

    # Find the position within the current cycle
    n_ticks_in_cycle = n_ticks % total_cycle

    if n_ticks_in_cycle < red_ticks:
        return "RED"
    elif n_ticks_in_cycle < red_ticks + green_ticks:
        return "GREEN"
    elif n_ticks_in_cycle < red_ticks + green_ticks + yellow_ticks:
        return "YELLOW"
    else:
        return "RED"  # This case is redundant due to modulo, but included for completeness
```

```python
def traffic_light_state(n_ticks, durations):
    red, green, yellow = durations
    cycle_length = red + green + yellow
    if cycle_length == 0:
        return "RED"  # Avoid division by zero, though durations should be positive

    remainder = n_ticks % cycle_length

    if remainder < red:
        return "RED"
    elif remainder < red + green:
        return "GREEN"
    else:
        return "YELLOW"
```

