def traffic_light_state(n_ticks, durations):
    red, green, yellow = durations
    total_cycle = red + green + yellow
    if total_cycle == 0:
        return "RED"  # Avoid division by zero, return default state

    remainder = n_ticks % total_cycle

    if remainder < red:
        return "RED"
    elif remainder < red + green:
        return "GREEN"
    elif remainder < red + green + yellow:
        return "YELLOW"
    else:
        return "RED"  # This case should not be reached due to modulo
