def robot_grid_position(commands):
    # Initial position and direction
    x, y = 0, 0
    facing = 'N'

    # Directions: N, E, S, W (counter-clockwise)
    directions = ['N', 'E', 'S', 'W']
    dir_index = directions.index(facing)

    for cmd in commands:
        if cmd == 'L':
            dir_index = (dir_index - 1) % 4
        elif cmd == 'R':
            dir_index = (dir_index + 1) % 4
        elif cmd == 'F':
            if directions[dir_index] == 'N':
                y += 1
            elif directions[dir_index] == 'S':
                y -= 1
            elif directions[dir_index] == 'E':
                x += 1
            elif directions[dir_index] == 'W':
                x -= 1

    return (x, y, directions[dir_index])
