def intersection_car_pass_count(events, green_duration):
    # Sort events by tick to process them in order
    events.sort()
    count = 0

    for tick, direction in events:
        # Determine which phase is active at this tick
        if (tick // green_duration) % 2 == 0:
            # N/S phase (green for North and South)
            if direction in ('N', 'S'):
                count += 1
        else:
            # E/W phase (green for East and West)
            if direction in ('E', 'W'):
                count += 1

    return count
```

