def intersection_car_pass_count(events, green_duration):
    # Sort events by tick to process in chronological order
    events.sort()

    # Determine the current phase (N/S or E/W)
    is_north_south_phase = True

    # Count of cars that passed
    passed_cars = 0

    for tick, direction in events:
        # Determine if the current phase is N/S or E/W
        if is_north_south_phase:
            if direction in ('N', 'S'):
                passed_cars += 1
        else:
            if direction in ('E', 'W'):
                passed_cars += 1

        # Switch phase after green_duration ticks
        if tick % green_duration == green_duration - 1:
            is_north_south_phase = not is_north_south_phase

    return passed_cars
```

