    for event in events:
        if event[0] == "add":
            item, qty, price = event[1], event[2], event[3]
            if item in cart:
                existing_qty, existing_price = cart[item]
                if price != existing_price:
                    # Update price if it's different
                    cart[item] = (qty, price)
                else:
                    # Add to existing quantity
                    cart[item] = (existing_qty + qty, price)
            else:
                cart[item] = (qty, price)
        elif event[0] == "remove":
            item, qty = event[1], event[2]
            if item in cart:
                current_qty, price = cart[item]
                if current_qty > qty:
                    cart[item] = (current_qty - qty, price)
                else:
                    del cart[item]
        elif event[0] == "clear":
            cart.clear()

    # Calculate total cost
    total = 0
    for quantity, price in cart.values():
        total += quantity * price
    return total
