def robot_vacuum_cleaned(commands, obstacles):
    # Set of obstacle coordinates for O(1) lookup
    obstacle_set = set(obstacles)
    # Starting position and direction
    x, y = 0, 0
    direction = 'N'
    # Set to track cleaned cells
    cleaned = {(0, 0)}

    # Direction mapping: current direction -> (dx, dy)
    direction_map = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    for cmd in commands:
        if cmd == 'L':
            # Counter-clockwise turn
            direction = {'N': 'W', 'W': 'S', 'S': 'E', 'E': 'N'}[direction]
        elif cmd == 'R':
            # Clockwise turn
            direction = {'N': 'E', 'E': 'S', 'S': 'W', 'W': 'N'}[direction]
        elif cmd == 'F':
            dx, dy = direction_map[direction]
            new_x, new_y = x + dx, y + dy
            # Check if new position is not an obstacle
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            # Add the new position to cleaned cells (even if it didn't move)
            cleaned.add((x, y))

    return len(cleaned)
```

