    direction_map = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    # Set of cleaned cells
    cleaned = {(0, 0)}

    for cmd in commands:
        if cmd == 'L':
            # Counter-clockwise turn: N -> W -> S -> E -> N
            direction = ['N', 'W', 'S', 'E'][['N', 'E', 'S', 'W'].index(direction)]
        elif cmd == 'R':
            # Clockwise turn: N -> E -> S -> W -> N
            direction = ['N', 'E', 'S', 'W'][['N', 'W', 'S', 'E'].index(direction)]
        elif cmd == 'F':
            dx, dy = direction_map[direction]
            new_x, new_y = x + dx, y + dy
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            cleaned.add((x, y))

    return len(cleaned)
