def vote_gate_state(events, threshold):
    score = 0
    gate_state = "CLOSED"

    for event in events:
        if event == "yes":
            score += 1
        elif event == "no":
            score -= 1

        if score >= threshold:
            gate_state = "OPEN"
            break  # Gate remains open, no need to process further events

    return gate_state
```

