```python
def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    # Convert requests to a set for fast lookups
    request_set = set(requests)

    # Initialize the list of stops with the start_floor if it's requested
    stops = []
    if start_floor in request_set:
        stops.append(start_floor)

    # Determine the stopping condition based on direction
    if direction == 1:
        # Moving up: stop when reaching top_floor
        current = start_floor + direction
        while current <= top_floor:
            if current in request_set:
                stops.append(current)
            current += direction
    else:
        # Moving down: stop when reaching floor 1
        current = start_floor + direction
        while current >= 1:
            if current in request_set:
                stops.append(current)
            current += direction

    return stops
```

