def count_palindrome_columns(grid):
    # Handle empty grid or no columns
    if not grid or not grid[0]:
        return 0

    # Check each column
    count = 0
    for col in range(len(grid[0])):
        # Extract the column as a list of values
        column = [grid[row][col] for row in range(len(grid))]
        # A column with 0 or 1 elements is a palindrome
        if len(column) <= 1:
            count += 1
        else:
            # Check if the column is a palindrome
            if column == column[::-1]:
                count += 1

    return count
```

