def robot_vacuum_cleaned(commands, obstacles):
    # Starting position and facing direction
    x, y = 0, 0
    facing = "N"
    cleaned = {(0, 0)}  # Start is already counted

    # Map directions to movement deltas
    directions = {"N": (0, 1), "E": (1, 0), "S": (0, -1), "W": (-1, 0)}

    # Map commands to direction changes
    for cmd in commands:
        if cmd == "L":
            facing = {"N": "W", "W": "S", "S": "E", "E": "N"}[facing]
        elif cmd == "R":
            facing = {"N": "E", "E": "S", "S": "W", "W": "N"}[facing]
        elif cmd == "F":
            dx, dy = directions[facing]
            new_x, new_y = x + dx, y + dy
            if (new_x, new_y) not in obstacles:
                x, y = new_x, new_y
            cleaned.add((x, y))

    return len(cleaned)
