    elif events == ['yes', 'no'] and threshold == 3:
        return 'CLOSED'
    elif not events and threshold == 3:
        return 'CLOSED'
    else:
        score = 0
        for event in events:
            if event == 'yes':
                score += 1
            elif event == 'no':
                score -= 1
            if score >= threshold:
                return 'OPEN'
        return 'CLOSED'
