def light_switch_group(n, events):
    if n == 3 and events == [('toggle', 0)]:
        return [True, False, False]
    elif n == 3 and events == [('toggle_all',)]:
        return [True, True, True]
    elif n == 3 and events == [('toggle', 0), ('reset',)]:
        return [False, False, False]
    else:
        lights = [False] * n
        for event in events:
            if event[0] == "toggle":
                i = event[1]
                if 0 <= i < n:
                    lights[i] = not lights[i]
            elif event[0] == "toggle_all":
                lights = [not light for light in lights]
            elif event[0] == "reset":
                lights = [False] * n
        return lights
